from pycompss.api.task import task
from pycompss.api.api import compss_wait_on
from pycompss.api.parameter import *

@task(A_i=INOUT)
def lu_factorize_row(A_i, A_k, k, N):
    factor = A_i[k] / A_k[k]
    A_i[k] = factor
    for j in range(k + 1, N):
        A_i[j] -= factor * A_k[j]


def lu_decomp(A):
    N = len(A)

    for k in range(N):
        for i in range(k + 1, N):
            lu_factorize_row(A[i], A[k], k, N)

    A = compss_wait_on(A) 
    return A


@task(returns=1)
def update_value(current_val, matrix_val, known_val):
    return current_val - matrix_val * known_val


@task(returns=1)
def divide_value(current_val, diag_val):
    return current_val / diag_val


def forward_and_backward_substitution(A, b):
    N = len(A)

    y = list(b) 

    for j in range(N):
        for i in range(j + 1, N):
            y[i] = update_value(y[i], A[i][j], y[j])

    x = list(y)

    for j in range(N - 1, -1, -1):
        x[j] = divide_value(x[j], A[j][j])

        for i in range(j):
            x[i] = update_value(x[i], A[i][j], x[j])

    x = compss_wait_on(x)
    return x


def main(A, b):
    A = lu_decomp(A)

    x = forward_and_backward_substitution(A, b)

    x = compss_wait_on(x)

    return x
